package org.tarish.adhan.data.quran

import android.content.Context
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import org.tarish.adhan.core.di.IoDispatcher
import org.tarish.adhan.domain.quran.Surah
import javax.inject.Inject
import javax.inject.Singleton

/** Generated by tools/quran/build_assets.py. `verses[0]` is verse 1 (Ahmadiyya numbering). */
@Serializable
private data class QuranFile(val surahs: List<SurahDto>)

@Serializable
private data class SurahDto(
    val n: Int,
    val name: String,
    val ar: String,
    val meaning: String,
    val place: String,
    val verses: List<String>,
)

/** The bundled Arabic text and surah list, read once (~1.4 MB) and kept in memory. */
@Singleton
class QuranAssets @Inject constructor(
    @ApplicationContext private val context: Context,
    private val json: Json,
    @IoDispatcher private val io: CoroutineDispatcher,
) {
    private val lock = Mutex()
    @Volatile private var cached: List<SurahDto>? = null

    private suspend fun load(): List<SurahDto> = cached ?: lock.withLock {
        cached ?: withContext(io) {
            context.assets.open(PATH).bufferedReader().use { json.decodeFromString<QuranFile>(it.readText()).surahs }
        }.also { cached = it }
    }

    suspend fun surahs(): List<Surah> = load().map {
        Surah(it.n, it.name, it.ar, it.meaning, makki = it.place == "makkah", verseCount = it.verses.size)
    }

    /** Arabic for verses 1..n of [surah]. */
    suspend fun arabic(surah: Int): List<String> = load()[surah - 1].verses

    companion object { const val PATH = "quran/quran.json" }
}
